 const rec=id=>s.recipes.find(r=>r.id===id),line=(id,qty,price)=>({recipeId:id,qty,unitPrice:price??rec(id).unitPrice,finishMinutes:rec(id).finishMinutes});
 const H=38,hist=C.addDays(start,-7*H),horizon=C.addDays(start,27);
