 for(let m=0;m<10;m++){const d=C.addDays(hist,30*m+3);if(d>=t)break;exp(d,'Packaging','Kraft bread bags and boxes',Math.round((38+rnd()*30)*100)/100);exp(C.addDays(d,12),'Delivery & mileage','Café and deli drops',Math.round((22+rnd()*14)*100)/100);if(m%3===0)exp(C.addDays(d,7),'Marketing','Market banner and flyers',Math.round((25+rnd()*40)*100)/100);}
 exp(C.addDays(hist,5),'Permits & insurance','Cottage food registration',100);exp(C.addDays(hist,9),'Permits & insurance','Product liability insurance',299);exp(C.addDays(hist,60),'Equipment','Banneton baskets (12)',96);exp(C.addDays(hist,150),'Equipment','Second baking steel',115);
