function ingredientForm(id){const i=ingredient(id)||{name:'',unit:'g',packSize:1000,packCost:'',stock:0,supplier:'',labelName:'',allergens:[],minStock:0};
 modal(id?'Edit ingredient':'Add a pantry ingredient','Pack size and price turn recipe amounts into whole packs to buy.',`<form id="ingredient-form" data-id="${esc(id||'')}"><div class="fields">${fld('name','Ingredient name',i.name,{attrs:'required maxlength="150"',full:true})}
 ${sel('unit','Base unit',[['g','Grams (g)'],['ml','Milliliters (ml)'],['each','Each']],i.unit)}${fld('packSize','Amount in one pack',i.packSize,{type:'number',attrs:'min="0.000001" step="any" required',hint:'In the base unit: 2.5 kg = 2500 g.'})}
 ${moneyFld('packCost','Price per pack',i.packCost??'','Leave blank if unknown. Enter 0 only when it’s genuinely free.')}${fld('stock','In your pantry now',i.stock,{type:'number',attrs:'min="0" step="any" required',hint:'In the same base unit.'})}
 ${fld('supplier','Supplier or shopping stop',i.supplier,{attrs:'maxlength="150"'})}${fld('minStock',`Keep at least (${i.unit})`,i.minStock||0,{type:'number',attrs:'min="0" step="any"',hint:'Below this, it goes on the restock list.'})}</div>
 <div class="form-section"><h3>For labels</h3><div class="fields">${fld('labelName','Name on labels',i.labelName||'',{attrs:'maxlength="500"',hint:'Optional, e.g. “unbleached wheat flour (wheat flour, malted barley flour)”.',full:true})}</div>
 <div class="day-picks" role="group" aria-label="Allergens" style="margin-top:10px">${C.allergenKeys.map(a=>`<label class="day-pick"><input type="checkbox" name="allergens" value="${a}" ${(i.allergens||[]).includes(a)?'checked':''}><span>${ALLERGENS[a]}</span></label>`).join('')}</div><p class="small dim" style="margin-top:6px">Tick what this ingredient contains. Every recipe using it shows the allergen on its label.</p></div><div class="notice" style="margin:14px 0 0"><span>The base unit locks once a recipe uses this ingredient.</span></div>${formFoot(id?'Save ingredient':'Add ingredient')}</form>`);}
const ingRows=()=>recipeRows.map((l,n)=>`<div class="line-row ing" data-index="${n}"><label>Ingredient ${n+1}<select data-ri="ingredientId">${state.ingredients.filter(i=>!i.archived||i.id===l.ingredientId).map(i=>`<option value="${esc(i.id)}" ${i.id===l.ingredientId?'selected':''}>${esc(i.name)} (${i.unit})</option>`).join('')}</select></label><label>Per batch (${esc(ingredient(l.ingredientId)?.unit||'')})<input data-ri="qty" type="number" min="0.000001" step="any" value="${l.qty}" required></label><button type="button" class="icon-action danger" data-action="remove-recipe-ingredient" data-index="${n}" aria-label="Remove ingredient ${n+1}">${ico('trash')}</button></div>`).join('');
function recipeForm(id){if(!state.ingredients.some(i=>!i.archived)){toast('Add at least one pantry ingredient first.');return ingredientForm();}
 const r=recipe(id)||{name:'',category:'',color:'#A46D4C',yield:12,activeMinutes:25,ovenMinutes:20,finishMinutes:2,unitPrice:3,packagingCost:.2,method:'',keepsDays:0,pieceWeight:0,labelNote:'',labelText:'',prepDays:0,prepMinutes:0,prepNote:'',ingredients:[{ingredientId:state.ingredients.find(i=>!i.archived).id,qty:100}]};recipeRows=clone(r.ingredients);recipeImg=undefined;
 modal(id?'Edit recipe':'Build a reusable recipe','Changes update estimates for unfinished orders. Saved order prices and completed batches stay as they are.',`<form id="recipe-form" data-id="${esc(id||'')}"><div class="fields">${fld('name','Recipe or product name',r.name,{attrs:'required maxlength="150"',full:true})}
 ${sel('category','Category',[['','Uncategorized'],...catList().map(c=>[c,c])],r.category||'',{attrs:''})}${fld('color','Recipe color',r.color,{type:'color'})}
 ${fld('yield','Sellable pieces per batch',r.yield,{type:'number',attrs:'min="1" step="1" required'})}${fld('activeMinutes','Hands-on minutes per batch',r.activeMinutes,{type:'number',attrs:'min="0" step="any" required',hint:'On baking day. Dough started earlier goes under Prep.'})}
 ${fld('ovenMinutes','Oven minutes per batch',r.ovenMinutes,{type:'number',attrs:'min="0" step="any" required',hint:'A reference, not an oven schedule.'})}${fld('finishMinutes','Finishing minutes per piece',r.finishMinutes,{type:'number',attrs:'min="0" step="any" required',hint:'Decorating, finishing and packing.'})}
 ${moneyFld('unitPrice','Default price per piece',r.unitPrice)}${moneyFld('packagingCost','Packaging cost per piece',r.packagingCost)}</div>
 <div class="form-section"><h3>Prep before baking day</h3><div class="fields">${sel('prepDays','Start it',[['0','On baking day (no prep day)'],['1','The day before'],['2','2 days before'],['3','3 days before']],String(r.prepDays||0))}${fld('prepMinutes','Prep minutes per batch',r.prepMinutes||0,{type:'number',attrs:'min="0" step="any" required',hint:'Levain, mixing, folds, shaping for the fridge.'})}
 ${fld('prepNote','What to do',r.prepNote||'',{attrs:'maxlength="1000" placeholder="e.g. Build levain 8am, mix 2pm, shape and retard overnight"',full:true})}</div><p class="small dim" style="margin-top:8px">Prep lands on the right day of the plan and the batch sheets, and counts toward that day’s hours.</p></div>
 <div class="form-section"><h3>Labels</h3><div class="fields">${fld('keepsDays','Keeps for (days)',r.keepsDays||0,{type:'number',attrs:'min="0" max="365" step="1"',hint:'Sets the best-by date. 0 leaves it off.'})}${fld('pieceWeight','Weight per piece (g)',r.pieceWeight||0,{type:'number',attrs:'min="0" step="any"',hint:'Prints a net weight. 0 leaves it off.'})}
 ${fld('labelNote','Extra label line',r.labelNote||'',{attrs:'maxlength="300" placeholder="e.g. Made in a kitchen that also handles tree nuts."',full:true})}${area('labelText','Ingredient list for labels',r.labelText||'',id?`Leave empty to use: ${esc(C.labelInfo(state,recipe(id)).auto?C.labelInfo(state,recipe(id)).ingredients:'the recipe’s ingredients, heaviest first')}`:'Leave empty to list the recipe’s ingredients, heaviest first.')}</div></div>
 <div class="form-section"><h3>Picture</h3><div class="pic-row"><div id="recipe-pic">${imgBox(id?prefs.images[id]:'',r.color)}</div><div class="actions"><label class="btn small">${ico('upload')}Choose a picture<input type="file" id="recipe-pic-file" accept="image/*" hidden></label>${button('Remove','recipe-pic-remove','small quiet')}</div><p class="small dim">Shown on recipe cards and in the table. Resized to 640×480 and kept on this computer. New categories: Settings → Recipe categories.</p></div></div><div class="form-section"><h3>Ingredients for one batch</h3><div id="recipe-rows">${ingRows()}</div>${button(ico('plus')+'Add ingredient','add-recipe-ingredient','small quiet')}</div>
 <div class="fields">${area('method','Your tested method and batch notes',r.method,'Batch sheets scale the amounts for you. Follow your own recipe, storage and food-safety procedures.')}</div>${formFoot(id?'Save recipe':'Add recipe')}</form>`,true);}
function newOrder(){const r=state.recipes.find(r=>!r.archived),refs=new Set(state.orders.map(o=>o.reference.toLowerCase())),ref=()=>{let n=state.orders.length+1;while(refs.has(`bw-${String(n).padStart(3,'0')}`))n++;return `BW-${String(n).padStart(3,'0')}`;};
 return {reference:ref(),customer:'',contact:'',dueDate:C.addDays(week,5),bakeDate:C.addDays(week,3),finishDate:C.addDays(week,4),status:'Confirmed',paid:0,payment:'Card',setupMinutes:15,extraCost:0,customerNote:'',kitchenNote:'',lines:r?[{recipeId:r.id,qty:48,unitPrice:r.unitPrice,finishMinutes:r.finishMinutes}]:[]};}
const lineRows=(lines,scope)=>lines.map((l,n)=>`<div class="line-row" data-index="${n}"><label>Product<select data-line="recipeId" data-scope="${scope}">${state.recipes.filter(r=>!r.archived||r.id===l.recipeId).map(r=>`<option value="${esc(r.id)}" ${r.id===l.recipeId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>${scope==='market'?'Pieces to bring':scope==='standing'?'Pieces each drop':'Pieces'}<input data-line="qty" data-scope="${scope}" type="number" min="1" step="1" value="${Number.isFinite(l.qty)?l.qty:''}" required></label><label>Price / piece<input data-line="unitPrice" data-scope="${scope}" type="number" min="0" step=".01" value="${Number.isFinite(l.unitPrice)?l.unitPrice:''}" required></label><label>Finish min / piece<input data-line="finishMinutes" data-scope="${scope}" type="number" min="0" step="any" value="${Number.isFinite(l.finishMinutes)?l.finishMinutes:''}" required></label><button type="button" class="icon-action danger" data-action="remove-line" data-scope="${scope}" data-index="${n}" aria-label="Remove product ${n+1}">${ico('trash')}</button></div>`).join('');
const orderFields=o=>`${fld('reference','Order reference',o.reference,{attrs:'required maxlength="100"'})}${fld('customer','Customer',o.customer,{attrs:'required maxlength="150"'})}${fld('contact','Contact or pickup details',o.contact,{attrs:'maxlength="250"',full:true})}
 ${fld('bakeDate','Bake date',o.bakeDate,{type:'date',attrs:'required'})}${fld('finishDate','Finish & pack date',o.finishDate,{type:'date',attrs:'required'})}${fld('dueDate','Pickup date',o.dueDate,{type:'date',attrs:'required'})}
 ${sel('payment','Payment method',[['Card','Card'],['Cash','Cash'],['Other','Other']],o.payment)}${fld('setupMinutes','Extra setup minutes',o.setupMinutes,{type:'number',attrs:'min="0" step="any" required'})}${moneyFld('extraCost','Extra packaging or order cost',o.extraCost)}${moneyFld('paid','Paid so far',o.paid)}
 ${area('customerNote','Note for the customer',o.customerNote)}${area('kitchenNote','Private kitchen note',o.kitchenNote,'Only on kitchen paperwork, never on the customer quote.')}`;
function orderForm(id){const o=order(id);if(!o)return simulator();orderRows=clone(o.lines);const q=C.quoteOrder(state,o),locked=state.completedRuns.some(r=>r.allocations.some(a=>a.orderId===o.id));
 modal(`${esc(o.reference)} · ${esc(o.customer)}`,`Pickup ${longDay(o.dueDate)} ${date(o.dueDate)} · bake ${date(o.bakeDate)} · finish ${date(o.finishDate)}`,
 `<div class="kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))">${tile('Order total',money(q.revenue),{tone:'pos',icon:'up'})}${tile('Still to collect',money(balance(o)),{tone:'pos',icon:'wallet'})}${tile('Estimated surplus',cash(q.surplus),{tone:'net',icon:'insights',note:'After costs and your time'})}</div>
 <div class="actions" style="margin-bottom:8px">${statusPill(o.status)}${button(ico('print')+'Print quote','print','small','data-k="quote" data-id="'+esc(id)+'"')}${button('Record payment','payment','small',`data-id="${esc(id)}"`)}${o.status==='Confirmed'?button('Mark ready','order-status','small',`data-id="${esc(id)}" data-status="Ready"`):''}${o.status==='Ready'?button('Mark collected','order-status','small',`data-id="${esc(id)}" data-status="Collected"`):''}${o.status!=='Confirmed'?button('Return to Confirmed','order-status','small quiet',`data-id="${esc(id)}" data-status="Confirmed"`):''}</div>
 ${allergyNote(o.customer)?`<div class="notice warning"><span><b>Allergies:</b> ${esc(allergyNote(o.customer))}</span>${button('Customer card','customer-form','small',`data-name="${esc(o.customer)}"`)}</div>`:''}
 <div class="actions msg-actions"><span class="small dim">Copy a message:</span>${button('Confirmation','msg-copy','small quiet',`data-id="${esc(o.id)}" data-k="confirm"`)}${button('Ready for pickup','msg-copy','small quiet',`data-id="${esc(o.id)}" data-k="ready"`)}${balance(o)>0.005?button('Payment reminder','msg-copy','small quiet',`data-id="${esc(o.id)}" data-k="remind"`):''}</div>
 ${o.menuId?`<div class="notice"><span>A pre-order from the weekly menu. It counts toward the menu’s limits until it’s canceled.</span>${button('Open the menu','go','small','data-go="menu"')}</div>`:''}
 ${o.standingId?`<div class="notice"><span>A drop from <b>${esc(standingOf(o)?.customer||'a standing order')}</b>’s standing order. Changes here are for this drop only.</span>${standingOf(o)?button('Open standing order','standing-form','small',`data-id="${esc(o.standingId)}"`):''}</div>`:''}
 ${locked?'<div class="notice"><span>This order has batches marked made. Undo them before changing quantities, dates or prices. Payments and status still work.</span></div>':''}
 <form id="order-form" data-id="${esc(id)}"><fieldset ${locked?'disabled':''} style="border:0;padding:0;margin:12px 0 0"><div class="form-section" style="margin-top:0;border:0;padding:0"><h3>Products</h3><div id="order-rows">${lineRows(orderRows,'order')}</div>${button(ico('plus')+'Add product','add-line','small quiet','data-scope="order"')}</div><div class="fields">${orderFields(o)}</div></fieldset>
 <div class="formfoot">${!locked&&o.status!=='Cancelled'?button('Cancel order','cancel-order','danger',`data-id="${esc(id)}"`):''}${!locked?button('Delete','delete-order','danger quiet',`data-id="${esc(id)}"`):''}<button type="button" class="btn" data-action="dismiss">Close</button>${!locked?'<button class="btn primary" type="submit">Save changes</button>':''}</div></form>`,true);}
function simulator(){if(!state.recipes.some(r=>!r.archived)){toast('Save a recipe first, so the order uses your real costs.');return recipeForm();}
 simDraft=newOrder();simDraft.customer='New inquiry';if(demo)simDraft.lines[0].finishMinutes=6;
 modal('Should you say yes to this order?',`A safe place to experiment: nothing is saved until you accept. Week of ${weekLabel(week)}.`,`<div class="sim"><form id="sim-form"><div class="fields">${fld('sim-customer','Customer or inquiry',simDraft.customer,{attrs:'data-sim="customer" required',full:true})}</div>
 <div class="form-section" style="margin-top:14px"><h3>Products</h3><div id="sim-rows">${lineRows(simDraft.lines,'sim')}</div>${button(ico('plus')+'Add product','add-line','small quiet','data-scope="sim"')}</div>
 <div class="fields">${fld('sim-bakeDate','Bake date',simDraft.bakeDate,{type:'date',attrs:`data-sim="bakeDate" min="${week}" max="${C.addDays(week,6)}" required`})}${fld('sim-finishDate','Finish & pack',simDraft.finishDate,{type:'date',attrs:`data-sim="finishDate" min="${week}" max="${C.addDays(week,6)}" required`})}
 ${fld('sim-dueDate','Pickup date',simDraft.dueDate,{type:'date',attrs:'data-sim="dueDate" required'})}${sel('sim-payment','Payment method',[['Card','Card'],['Cash','Cash'],['Other','Other']],simDraft.payment,{attrs:'data-sim="payment"'})}
 ${fld('sim-setupMinutes','Extra setup minutes',simDraft.setupMinutes,{type:'number',attrs:'data-sim="setupMinutes" min="0" step="any" required'})}${fld('sim-extraCost','Extra packaging or order cost',0,{type:'number',attrs:'data-sim="extraCost" min="0" step=".01" required'})}</div>
 <div class="form-section"><h3>Explore a workable version</h3><div class="sim-ideas">${button('Simpler finish · 2 min','sim-simple','small')}${button('Use recipe times','sim-default','small')}${button('Try available days','sim-days','small')}${button('Use the target quote','sim-price','small')}</div><p class="small dim" style="margin-top:8px">These change this draft only. Pick dates and decoration time that suit your recipe and your promise to the customer.</p></div></form>
 <aside class="sim-out" id="sim-out" aria-live="polite"></aside></div>`,true);updateSimulation();}
function suggestedQuote(result){const q=result.quote,d=result.delta,rate=simDraft.payment==='Card'?state.settings.cardRate/100:0,fixed=simDraft.payment==='Card'?state.settings.fixedFee:0;if(q.minPriceAtTarget===null||d.ingredientCost===null)return null;return Math.max(q.minPriceAtTarget,(d.ingredientCost+d.packagingCost+d.laborAllowance+fixed)/(1-rate-state.settings.targetMargin/100));}
function updateSimFields(){for(const e of $$('[data-sim]'))e.value=simDraft[e.dataset.sim];$('#sim-rows').innerHTML=lineRows(simDraft.lines,'sim');updateSimulation();}
function updateSimulation(){const out=$('#sim-out');if(!out)return;try{simResult=C.simulateOrder(state,simDraft,week);const {quote:q,delta:d}=simResult,target=suggestedQuote(simResult),priceOK=target!==null&&q.revenue+0.00001>=target,good=simResult.fits&&priceOK;
  out.innerHTML=`<div class="verdict ${!simResult.fits?'bad':!priceOK?'warn':''}"><div class="eyebrow">Before you promise it</div><h3>${!simResult.fits?'This version overloads your week':!priceOK?'It fits. The price needs a look':'A workable version of this order'}</h3><p>${!simResult.fits?simResult.conflicts.map(x=>`${longDay(x.date)}: ${mins(x.overMinutes)} over your hours`).join(' · '):'The hands-on work fits the hours you set for each day.'}</p></div>
  <div class="sim-tiles">${tile('Extra hands-on work',mins(d.activeMinutes),{icon:'clock',note:'Whole batches plus finishing'})}${tile('Extra batches',num(d.batches),{icon:'oven',note:`${num(d.units)} pieces ordered`})}${tile('Extra shopping',cash(d.shoppingCost),{icon:'cart',tone:'neg',note:'Change in whole packs to buy'})}${tile('Extra surplus',cash(d.surplus),{icon:'insights',tone:d.surplus!==null&&d.surplus<0?'neg':'net',note:'After costs, fees and your time'})}</div>
  <div class="receipt"><div class="row"><span>Customer quote</span><strong class="number">${money(q.revenue)}</strong></div><div class="row"><span>Extra ingredients</span><strong class="number">${cash(d.ingredientCost)}</strong></div><div class="row"><span>Packaging and extras</span><strong class="number">${money(d.packagingCost)}</strong></div><div class="row"><span>Payment fees</span><strong class="number">${money(d.fees)}</strong></div><div class="row"><span>Your time (${money(state.settings.hourlyRate)}/h)</span><strong class="number">${money(d.laborAllowance)}</strong></div><div class="row total"><span>Suggested minimum quote</span><strong>${cash(target)}</strong></div></div>
  ${q.unknownCosts.length?`<div class="notice warning"><span>Missing prices: ${esc(q.unknownCosts.join(', '))}. Add them before relying on the estimate.</span></div>`:d.ingredientCost===null?'<div class="notice warning"><span>Other batches this week have missing prices. Complete them in Pantry before relying on this comparison.</span></div>':''}
  ${button(good?'Accept and build the plan':'Accept this version anyway','accept-sim',good?'primary full':'full')}<p class="small dim" style="margin-top:8px">Accepting adds the order, its batches, shopping and packing ticket. No payment is taken. The minimum quote covers the whole batches this order needs, your time and your ${state.settings.targetMargin}% margin; taxes and unentered overheads aren’t included.</p>`;
  const e=$('#form-error');if(e)e.hidden=true;}catch(e){simResult=null;out.innerHTML=`<div class="notice warning"><span><b>Complete this draft.</b> ${esc(e.message)}</span></div>`;}}
function paymentForm(id){const o=order(id);modal('Record a payment',`${esc(o.customer)} · ${esc(o.reference)} · order total ${money(rev(o))}`,`<form id="payment-form" data-id="${esc(id)}"><div class="fields">${moneyFld('paid','Total paid so far',o.paid,'The running total, including earlier deposits.',true)}</div>${formFoot('Save payment')}</form>`);}
function receiveForm(id){const i=ingredient(id);modal('Receive pantry stock',`${esc(i.name)} · ${qty(i.stock,i.unit)} in the pantry now`,`<form id="receive-form" data-id="${esc(id)}"><div class="fields">${fld('qty',`Amount received (${i.unit})`,i.packSize,{type:'number',attrs:'min="0.000001" step="any" required',hint:'Adds to your stock; it doesn’t replace it.',full:true})}</div>${formFoot('Add to pantry')}</form>`);}
function capacityForm(){go('settings');setTimeout(()=>{const f=$('#capacity-form');f?.scrollIntoView({block:'center'});f?.querySelector('input')?.focus();},60);}
function importForm(){importPreview=null;modal('Bring your orders in once','Use the CSV template and the exact recipe names in your library. Repeat an order reference for several products; existing references are skipped.',`<div class="actions" style="margin-bottom:12px">${button(ico('down')+'Download the template','csv-template','small')}${button(ico('upload')+'Choose a CSV file','csv-file','small')}</div><div class="fields">${area('csvText','Or paste the CSV here','','Up to 4 MB. On a multi-product order, repeat the same paid amount on each row; it counts once.')}</div><div id="import-result" style="margin-top:12px"></div><div class="formfoot"><button type="button" class="btn" data-action="dismiss">Cancel</button>${button('Preview import','preview-import','primary')}</div>`,true);}
function previewImport(){const text=$('[name=csvText]').value;try{const copy=clone(state),old=new Set(copy.orders.map(o=>o.id)),r=C.importOrders(copy,text);importPreview={text,r};
  $('#import-result').innerHTML=`<div class="notice"><span><b>${plural(r.imported,'order')} ready · ${plural(r.skipped,'existing reference')} skipped.</b> Nothing is added yet.<br>${copy.orders.filter(o=>!old.has(o.id)).slice(0,10).map(o=>`${esc(o.reference)}: ${esc(o.customer)} (${num(o.lines.reduce((n,l)=>n+l.qty,0))} pieces)`).join('<br>')}</span>${r.imported?button('Confirm import','confirm-import','primary small'):''}</div>`;}
 catch(e){importPreview=null;$('#import-result').innerHTML=`<div class="notice refused"><span><b>Not imported.</b> ${esc(e.message)}</span></div>`;}}

/* ================================================================================
   Kitchen paperwork: printed on its own, never the screen around it
   ================================================================================ */
const printHead=(title,subtitle,right='')=>`<header class="print-head"><div><div class="eyebrow">${esc(state.settings.business||'Your bakery')}</div><h1>${esc(title)}</h1><p class="mini">${esc(subtitle)}</p></div><div style="text-align:right">${right}<p class="mini">Prepared ${esc(date(today()))}</p></div></header>`;
const printFoot=(text='')=>`<footer class="foot">${esc(text||'Bakeweek Studio · prepared from your current workspace.')}${demo?'<br>Made-up sample data. The recipes are costing examples, not tested recipes.':''}</footer>`;
function outShopping(p){const rows=p.shopping.filter(i=>i.required>0);
 return `<section class="sheet">${printHead('Shopping list',`Production week ${weekLabel(p.start)}`,`<b>${esc(cash(p.totals.shoppingCost))}</b>`)}<p class="mini">Batches still to make only. Pantry stock is subtracted and purchases round up to whole packs. Stock isn’t reserved for other weeks.</p>
 ${rows.length?`<table><thead><tr><th>Ingredient / supplier</th><th class="r">Need</th><th class="r">Pantry</th><th class="r">Short</th><th>Buy</th><th class="r">Est. spend</th></tr></thead><tbody>${rows.map(i=>`<tr><td><span class="box"></span><b>${esc(i.name)}</b>${i.supplier?`<br><span class="mini">${esc(i.supplier)}</span>`:''}</td><td class="r">${esc(qty(i.required,i.unit))}</td><td class="r">${esc(qty(i.stock,i.unit))}</td><td class="r">${esc(qty(i.shortfall,i.unit))}</td><td>${i.packs?`<b>${plural(i.packs,'pack')}</b><br><span class="mini">${esc(qty(i.packSize,i.unit))} each · ${esc(qty(i.buyQty,i.unit))}</span>`:'Covered'}</td><td class="r">${esc(i.packs?cash(i.cost):money(0))}</td></tr>`).join('')}</tbody></table>`:'<p>No ingredients to buy for this week.</p>'}
 <div class="line total"><span>Planned purchase cost</span><b>${esc(cash(p.totals.shoppingCost))}</b></div><p class="mini">Use Receive planned shopping in the app only after the listed packs arrive. Record partial or different purchases in Pantry.</p>${printFoot()}</section>`;}
function outRun(run,made){const r=recipe(run.recipeId),method=r?.method||'';
 return `<article class="blk"${method.length>1400?' style="break-inside:auto"':''}><div class="blk-head"><div><div class="eyebrow">${made?'Already made':'To make'} · ${esc(longDay(run.date))} ${esc(date(run.date))}</div><h2>${esc(run.recipeName)}</h2></div><div style="text-align:right"><b>${plural(run.batches,'batch','batches')}</b><p class="mini">${num(run.produced)} made · ${num(run.required)} for orders · ${num(run.extra)} extra</p></div></div>
 <p class="mini">Hands-on ${esc(mins(run.activeMinutes))} · oven ${esc(mins(run.ovenMinutes))} (reference) · ingredients ${esc(cash(run.ingredientCost))}</p>${r?.prepDays?`<p class="mini"><b>Start ${esc(longDay(C.addDays(run.date,-r.prepDays)))}:</b> ${esc(r.prepNote||'dough prep')} · ${esc(mins(run.batches*r.prepMinutes))}</p>`:''}
 <table><thead><tr><th>Scaled ingredient</th><th class="r">For this run</th></tr></thead><tbody>${run.ingredients.map(i=>`<tr><td><span class="box"></span>${esc(i.name)}</td><td class="r"><b>${esc(qty(i.qty,i.unit))}</b></td></tr>`).join('')}</tbody></table>
 ${method?`<h3>Method</h3><div class="method">${esc(method)}</div>`:''}
 <h3>Allocate to these orders</h3><table><thead><tr><th>Order / customer</th><th>Pickup</th><th class="r">Pieces</th></tr></thead><tbody>${run.allocations.map(a=>{const o=order(a.orderId);return `<tr><td>${esc(o?.reference||'')} · ${esc(o?.customer||'Order')}</td><td>${esc(o?date(o.dueDate):'')}</td><td class="r">${num(a.qty)}</td></tr>`;}).join('')}</tbody></table>
 ${run.allocations.map(a=>order(a.orderId)).filter((o,i,l)=>o&&o.kitchenNote&&l.findIndex(x=>x?.id===o.id)===i).map(o=>`<p class="mini" style="white-space:pre-wrap"><b>${esc(o.reference)} kitchen note:</b> ${esc(o.kitchenNote)}</p>`).join('')}
 <p class="mini">${made?'Recorded as made: its ingredients were taken from the pantry then.':'When it’s done, choose Mark batch made in the app to take its ingredients from the pantry once.'}${run.extra?` ${num(run.extra)} extra pieces aren’t assigned to an order.`:''}</p></article>`;}
// dough started before its baking day, by the day it's done: on screen and on the printed batch sheets
function prepTable(preps,print=false){if(!preps.length)return '';const rows=preps.map(x=>`<tr${x.made?' class="dim"':''}><td>${print?'<span class="box"></span>':''}<strong>${esc(longDay(x.date))}</strong>${print?'':`<small class="dim" style="display:block">${date(x.date)}</small>`}</td><td><strong>${esc(x.recipeName)}</strong>${x.note?`<small class="${print?'mini':'dim'}" style="display:block">${esc(x.note)}</small>`:''}</td><td>${esc(dayname(x.bakeDate)+' '+date(x.bakeDate))}</td><td class="${print?'r':'num'}">${num(x.batches)}</td><td class="${print?'r':'num'}">${esc(mins(x.minutes))}</td></tr>`).join('');
 return print?`<h3>Dough prep this week</h3><table><thead><tr><th>Day</th><th>Recipe</th><th>Bakes</th><th class="r">Batches</th><th class="r">Time</th></tr></thead><tbody>${rows}</tbody></table>`:`<div class="table-wrap"><table><thead><tr><th>Prep day</th><th>Recipe</th><th>Bakes</th><th class="num">Batches</th><th class="num">Time</th></tr></thead><tbody>${rows}</tbody></table></div>`;}
function outBatches(p){const runs=[...p.runs.map(run=>({run,made:false})),...p.completedRuns.map(run=>({run,made:true}))].sort((a,b)=>a.run.date.localeCompare(b.run.date)||a.run.recipeName.localeCompare(b.run.recipeName));
 return `<section class="sheet">${printHead('Batch sheets',`Production week ${weekLabel(p.start)}`,`<b>${plural(p.totals.batches,'batch','batches')}</b>`)}<p class="mini">Amounts are for each whole production run. Finishing and packing are listed by order on the packing tickets.</p>${prepTable(p.days.flatMap(d=>d.preps),true)}${runs.length?runs.map(x=>outRun(x.run,x.made)).join(''):'<p>No batches this week.</p>'}${printFoot()}</section>`;}
function outPacking(p){const os=p.orders.slice().sort((a,b)=>a.dueDate.localeCompare(b.dueDate)||a.customer.localeCompare(b.customer));
 return `<section class="sheet">${printHead('Pack & collect',`Pickups ${weekLabel(p.start)}`,`<b>${plural(os.length,'pickup')}</b>`)}<p class="mini">Kitchen tickets: check what the customer asked for, finish the work and update the status in the app.</p>
 ${os.length?os.map(o=>`<article class="blk"><div class="blk-head"><div><div class="eyebrow">${esc(o.reference)} · ${esc(statusLabel(o.status))}</div><h2>${esc(o.customer)}</h2>${o.contact?`<p class="mini">${esc(o.contact)}</p>`:''}</div><div style="text-align:right"><b>Pickup ${esc(longDay(o.dueDate))} ${esc(date(o.dueDate))}</b><p class="mini">Bake ${esc(date(o.bakeDate))} · finish ${esc(date(o.finishDate))}</p></div></div>
  <table><thead><tr><th>Pack each item</th><th class="r">Pieces</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td><span class="box"></span>${esc(recipe(l.recipeId)?.name||'Product')}</td><td class="r"><b>${num(l.qty)}</b></td></tr>`).join('')}</tbody></table>
  ${allergyNote(o.customer)?`<p><b>ALLERGIES: ${esc(allergyNote(o.customer))}</b></p>`:''}${o.customerNote?`<p style="white-space:pre-wrap"><b>Customer note:</b> ${esc(o.customerNote)}</p>`:''}${o.kitchenNote?`<p style="white-space:pre-wrap"><b>Kitchen note:</b> ${esc(o.kitchenNote)}</p>`:''}
  <p class="mini">Finishing and setup: about ${esc(mins(o.setupMinutes+o.lines.reduce((n,l)=>n+l.qty*l.finishMinutes,0)))}</p><div class="line"><span>Quoted / paid so far</span><b>${esc(money(rev(o)))} / ${esc(money(o.paid))}</b></div><div class="line total"><span>Balance due</span><b>${esc(money(balance(o)))}</b></div>
  <p class="mini"><span class="box"></span>Finished &amp; packed &nbsp; <span class="box"></span>Balance recorded &nbsp; <span class="box"></span>Collected</p></article>`).join(''):'<p>No pickups this week.</p>'}${printFoot()}</section>`;}
// the customer's copy uses only agreed prices, payments and customer notes: never costs or kitchen notes
function outQuote(id){const o=order(id);if(!o)throw Error('Open a saved order before printing its quote.');const total=rev(o);
 return `<section class="sheet">${printHead('Order quote',`Prepared for ${o.customer}`,`<b>${esc(o.reference)}</b>`)}<div class="cols"><div><h3>Customer</h3><p>${esc(o.customer)}${o.contact?`<br>${esc(o.contact)}`:''}</p></div><div><h3>Pickup</h3><p>${esc(longDay(o.dueDate))} ${esc(date(o.dueDate))}, ${o.dueDate.slice(0,4)}</p></div></div>
 <table><thead><tr><th>Item</th><th class="r">Pieces</th><th class="r">Price each</th><th class="r">Amount</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(recipe(l.recipeId)?.name||'Product')}</td><td class="r">${num(l.qty)}</td><td class="r">${esc(money(l.unitPrice))}</td><td class="r">${esc(money(l.qty*l.unitPrice))}</td></tr>`).join('')}</tbody></table>
 <div style="max-width:320px;margin-left:auto"><div class="line"><span>Subtotal</span><b>${esc(money(total))}</b></div><div class="line"><span>Paid so far</span><b>${esc(money(o.paid))}</b></div><div class="line total"><span>Balance due</span><b>${esc(money(balance(o)))}</b></div></div>
 <p class="mini">All amounts in ${esc(state.settings.currency)}. Tax isn’t calculated on this quote.</p>${o.customerNote?`<h3>Order notes</h3><div class="method">${esc(o.customerNote)}</div>`:''}${printFoot('Thank you for supporting '+(state.settings.business||'our bakery')+'.')}</section>`;}
function printOut(kind,id){try{const p=plan(),html=kind==='quote'?outQuote(id):kind==='menu'?outMenu():kind==='packet'?outShopping(p)+outBatches(p)+outPacking(p):kind==='shopping'?outShopping(p):kind==='batches'?outBatches(p):kind==='packing'?outPacking(p):'';
 if(!html)return print();closeModal();$('#print-area').innerHTML=html;document.body.classList.add('printing');
 requestAnimationFrame(()=>requestAnimationFrame(()=>{try{print();}catch{document.body.classList.remove('printing');toast('Printing couldn’t open. Try again in Chrome or Edge on a computer.');}}));}catch(e){toast(e.message);}}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
function shoppingText(){const p=plan(),short=p.shopping.filter(i=>i.packs>0).sort((a,b)=>(a.supplier||'').localeCompare(b.supplier||'')||a.name.localeCompare(b.name));
 const lines=[state.settings.business||'Your bakery','BAKEWEEK SHOPPING LIST',`Production week: ${weekLabel(p.start)}`,''];if(!short.length)lines.push('Nothing to buy for the batches still to make.');
 for(const i of short)lines.push(`[ ] ${i.name}`,`    Buy ${plural(i.packs,'pack')} x ${qty(i.packSize,i.unit)} = ${qty(i.buyQty,i.unit)}`,`    Need ${qty(i.required,i.unit)} | Pantry ${qty(i.stock,i.unit)} | Short ${qty(i.shortfall,i.unit)}`,`    Supplier: ${i.supplier||'Not entered'} | Estimated spend: ${cash(i.cost)}`,'');
 lines.push(`Planned purchase cost: ${cash(p.totals.shoppingCost)}`,'','Purchases round up to whole packs. Missing prices make the estimate incomplete.','Use Receive planned shopping only after every listed pack arrives.','Generated by Bakeweek Studio.');if(demo)lines.push('Made-up sample data.');
 download(`Bakeweek_Shopping_${week}.txt`,lines.join('\r\n')+'\r\n','text/plain;charset=utf-8');toast('Shopping list downloaded. Receive purchases only when they arrive.');}
// quote every CSV field and neutralize spreadsheet formulas in text the user typed
const csvCell=v=>{let t=String(v??'');if(typeof v!=='number'&&(/^\s*[=+\-@]/.test(t)||/^[\t\r\n]/.test(t)))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};
function exportOrders(){const rows=[['Order','Customer','Product','Quantity','Unit price','Pickup date','Bake date','Finish date','Finish minutes','Paid','Payment','Notes']];
 for(const o of state.orders.filter(o=>o.status!=='Cancelled'&&!isMarket(o)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)||a.reference.localeCompare(b.reference)))for(const l of o.lines)rows.push([o.reference,o.customer,recipe(l.recipeId)?.name||l.recipeId,l.qty,l.unitPrice,o.dueDate,o.bakeDate,o.finishDate,l.finishMinutes,o.paid,o.payment,o.customerNote||'']);
 download(`Bakeweek_Orders_${today()}.csv`,'﻿'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n','text/csv;charset=utf-8');toast(`${plural(rows.length-1,'order line')} exported. A CSV isn’t a backup: use Download backup for that.`);}

/* ================================================================================
   Events: one delegated handler per event type
   ================================================================================ */
function go(id){screen=id;document.body.classList.remove('menu-open');render();scrollTo({top:0});$('#content').focus({preventScroll:true});}
const setWeek=w=>{week=C.monday(w);selectedDay='';UI.cal.month='';render();};
const ACTIONS={
 go:b=>{go(b.dataset.go);if(b.dataset.anchor)setTimeout(()=>document.getElementById(b.dataset.anchor)?.scrollIntoView({block:'start'}),50);},menu:()=>document.body.classList.toggle('menu-open'),
 'rail-toggle':()=>{railMin=!railMin;ls.set(RAIL_KEY,railMin?'1':'0');applyRail();},
 'prev-week':()=>setWeek(C.addDays(week,-7)),'next-week':()=>setWeek(C.addDays(week,7)),'this-week':()=>setWeek(today()),
 'year-shift':b=>setWeek(C.addDays(week,364*+b.dataset.d)),
 'select-day':b=>{selectedDay=b.dataset.date;if(screen!=='week')screen='week';render();},
 pulse:b=>showPulse(+$('#pulse').dataset.at+ +b.dataset.d),'pulse-to':b=>showPulse(+b.dataset.i),
 page:b=>{UI[screen].page+=+b.dataset.d;render();},'status-filter':b=>{UI.orders.status=b.dataset.k;UI.orders.page=0;render();},
 'ask-ok':()=>{const f=askFn;askFn=null;closeModal();f?.();},dismiss:closeModal,
 undo:()=>{if(!undoState)return;state=undoState.state;prefs=undoState.prefs;undoState=null;save();render();toast('Undone');},
 sample:()=>{closeModal();toggleSample();},backup,restore:()=>$('#restore-file').click(),recovery:()=>download('Bakeweek_Recovery_Data.txt',recoveryRaw,'text/plain'),reload:()=>location.reload(),
 'choose-folder':chooseFolder,'reconnect-folder':reconnectFolder,'banner-hide':()=>{bannerHidden=true;renderStatus();},
 theme:b=>commit((s,p)=>{p.theme=b.dataset.k;},'Palette changed'),
 fresh:()=>ask('Start fresh?','This clears every ingredient, recipe, order and batch record. Download a backup first if you may need it. You can undo straight after.','Start fresh',()=>commit(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,C.createBlank());},'Started fresh')),
 tour:()=>openTour(false),'tour-step':b=>{tourAt+=+b.dataset.d;renderTour();$('#welcome [autofocus]')?.focus();},'tour-close':closeTour,'tour-sample':()=>{closeTour();if(!demo)toggleSample();},
 print:b=>printOut(b.dataset.k,b.dataset.id),'shopping-text':shoppingText,'export-orders':exportOrders,
 'ingredient-form':b=>ingredientForm(b.dataset.id),'recipe-form':b=>recipeForm(b.dataset.id),'order-form':b=>{const o=order(b.dataset.id);return o&&isMarket(o)?marketForm(o.id):orderForm(b.dataset.id);},simulator,
 capacity:capacityForm,payment:b=>paymentForm(b.dataset.id),'receive-ingredient':b=>receiveForm(b.dataset.id),'import-orders':importForm,
 'csv-template':()=>download('Bakeweek_Order_Import_Template.csv',C.orderCSVTemplate(state),'text/csv'),'csv-file':()=>$('#csv-file').click(),'preview-import':previewImport,
 'confirm-import':()=>{if(!importPreview||$('[name=csvText]').value!==importPreview.text)return toast('Preview the current CSV first.');const r=commit(s=>C.importOrders(s,importPreview.text),'Orders imported');if(r.ok){closeModal();go('orders');}},
 'add-recipe-ingredient':()=>{const used=new Set(recipeRows.map(l=>l.ingredientId)),i=state.ingredients.find(i=>!i.archived&&!used.has(i.id));if(!i)return formError('Every pantry ingredient is already in this recipe.');recipeRows.push({ingredientId:i.id,qty:100});$('#recipe-rows').innerHTML=ingRows();},
 'remove-recipe-ingredient':b=>{if(recipeRows.length===1)return formError('Keep at least one ingredient in the recipe.');recipeRows.splice(+b.dataset.index,1);$('#recipe-rows').innerHTML=ingRows();},
 'add-line':b=>lineEdit(b,'add'),'remove-line':b=>lineEdit(b,'remove'),
 'sim-simple':()=>{simDraft.lines.forEach(l=>l.finishMinutes=2);updateSimFields();},'sim-default':()=>{simDraft.lines.forEach(l=>l.finishMinutes=recipe(l.recipeId).finishMinutes);updateSimFields();},
 'sim-price':()=>{if(!simResult||suggestedQuote(simResult)===null)return toast('Add ingredient prices for every planned batch and this draft first.');const q=simResult.quote,target=Math.max(q.revenue,suggestedQuote(simResult)),total=simDraft.lines.reduce((n,l)=>n+l.qty,0);simDraft.lines.forEach(l=>l.unitPrice=Math.ceil((q.revenue?l.unitPrice*target/q.revenue:target/total)*100)/100);updateSimFields();},
 'sim-days':()=>{let best=null;for(let d=simDraft.bakeDate;d<=C.addDays(week,6)&&d<=simDraft.dueDate;d=C.addDays(d,1))for(let f=d;f<=C.addDays(week,6)&&f<=simDraft.dueDate;f=C.addDays(f,1)){try{const c={...simDraft,bakeDate:d,finishDate:f},r=C.simulateOrder(state,c,week),score=r.after.totals.overMinutes;if(!best||score<best.score)best={c,score};}catch{}}
  if(!best)return toast('Use valid dates in this week to try alternatives.');simDraft=best.c;updateSimFields();toast(best.score?'That’s the least overloaded option from the bake date on.':'These dates fit your hours. Review them before accepting.');},
 'accept-sim':()=>{if(!$('#sim-form').reportValidity()||!simResult)return;const r=commit(s=>C.addOrder(s,simDraft),'Order accepted. The plan, shopping and packing are ready.');if(r.ok){closeModal();selectedDay=simDraft.finishDate;go('week');}},
 'recipe-status':b=>{UI.recipes.status=b.dataset.k;render();},'recipe-view':b=>commit((s,p)=>{p.recipeView=b.dataset.k;}),
 'recipe-pic-remove':()=>{recipeImg=null;$('#recipe-pic').innerHTML=imgBox('',$('#recipe-form [name=color]').value);},
 'cat-move':b=>{const i=+b.dataset.i,j=i+ +b.dataset.d;commit((s,p)=>{const l=catList();for(const c of l)p.categoryColors[c]=catColor(c);[l[i],l[j]]=[l[j],l[i]];p.categories=l;},'Category moved');},
 'cat-rename':b=>{const old=catList()[+b.dataset.i];modal('Rename category',`${esc(old)} · every recipe in it moves to the new name.`,`<form id="cat-form" data-old="${esc(old)}"><div class="fields">${fld('name','New name',old,{attrs:'required maxlength="80"',full:true})}</div>${formFoot('Rename')}</form>`);},
 'cat-delete':b=>{const c=catList()[+b.dataset.i],n=state.recipes.filter(r=>r.category===c).length;ask(`Delete “${esc(c)}”?`,n?`Its ${plural(n,'recipe')} become Uncategorized; nothing else changes. You can undo straight after.`:'It has no recipes. You can undo straight after.','Delete category',()=>commit((s,p)=>{for(const r of s.recipes.filter(r=>r.category===c))C.updateRecipe(s,r.id,{category:''});p.categories=catList().filter(x=>x!==c);delete p.categoryColors[c];},'Category deleted'));},
 'archive-recipe':b=>{const r=recipe(b.dataset.id);ask(r.archived?'Activate this recipe?':'Archive this recipe?',r.archived?'It becomes available for new orders again.':'Existing orders keep it; it’s hidden when you add new orders.',r.archived?'Activate':'Archive',()=>commit(s=>C.updateRecipe(s,r.id,{archived:!r.archived}),r.archived?'Recipe activated':'Recipe archived'),!r.archived);},
 'complete-run':b=>{const r=plan().runs.find(x=>x.key===b.dataset.key);if(!r)return;ask('Mark this batch made?',`This takes the ingredients for ${plural(r.batches,'batch','batches')} of ${esc(r.recipeName)} from your pantry and records ${num(r.required)} pieces for orders. You can undo it.`,'Mark made',()=>commit(s=>C.completeRun(s,b.dataset.key,week),'Batch recorded. Pantry stock updated.'),false);},
 'undo-run':b=>ask('Undo this batch?','Its exact ingredient amounts go back to the pantry and the work becomes pending again. Affected orders must be Confirmed.','Undo batch',()=>commit(s=>C.undoRun(s,b.dataset.id),'Batch undone. Ingredients restored.')),
 'receive-shopping':()=>{const n=plan().shopping.filter(x=>x.packs>0).length;if(!n)return toast('Nothing left to buy for this week.');ask('Receive planned shopping?',`This adds the recommended whole packs for ${plural(n,'ingredient')} to your pantry. Use it only after they’ve actually arrived.`,'Receive',()=>commit(s=>C.receiveShopping(s,week),'Planned shopping added to the pantry'),false);},
 'order-status':b=>{closeModal();commit(s=>C.setOrderStatus(s,b.dataset.id,b.dataset.status),`Order marked ${statusLabel(b.dataset.status).toLowerCase()}`);},
 'cancel-order':b=>ask('Cancel this order?','It leaves the plan, shopping and packing. The order stays in your order book, and you can undo this.','Cancel order',()=>commit(s=>C.setOrderStatus(s,b.dataset.id,'Cancelled'),'Order canceled')),
 'delete-order':b=>ask('Delete this order?','It’s removed from your order book and every plan. You can undo straight after.','Delete order',()=>commit(s=>C.deleteOrder(s,b.dataset.id),'Order deleted')),
};
function lineEdit(b,kind){const scope=b.dataset.scope,lines=rowsOf(scope);
 if(kind==='add'){const r=state.recipes.find(r=>!r.archived&&!lines.some(l=>l.recipeId===r.id));if(!r)return formError('Every active product is already on the list.');lines.push({recipeId:r.id,qty:12,unitPrice:r.unitPrice,finishMinutes:r.finishMinutes});}
 else{if(lines.length===1)return formError('Keep at least one product.');lines.splice(+b.dataset.index,1);}
 redrawRows(scope);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||b.tagName==='INPUT')return;const f=ACTIONS[b.dataset.action];if(!f)return;try{f(b);}catch(err){toast(err.message);}});
document.addEventListener('keydown',e=>{
 const el=e.target;if((e.key==='Enter'||e.key===' ')&&el.matches?.('[role=button][data-action]')&&!/BUTTON|A/.test(el.tagName)){e.preventDefault();el.click();return;}
 if(e.key==='Escape')document.body.classList.remove('menu-open');
 if(e.key.toLowerCase()==='n'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!/INPUT|TEXTAREA|SELECT/.test(el.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();simulator();}});
document.addEventListener('input',e=>{const x=e.target;
 if(x.id==='search'&&UI[screen]){UI[screen].q=x.value;if('page' in UI[screen])UI[screen].page=0;clearTimeout(UI.t);UI.t=setTimeout(render,250);return;}
 if(x.dataset.sim&&simDraft){simDraft[x.dataset.sim]=['setupMinutes','extraCost'].includes(x.dataset.sim)?+x.value:x.value;updateSimulation();}
 if(x.dataset.line&&x.tagName!=='SELECT'){const lines=rowsOf(x.dataset.scope),i=+x.closest('[data-index]').dataset.index;lines[i][x.dataset.line]=x.value===''?NaN:+x.value;if(x.dataset.scope==='sim')updateSimulation();if(x.dataset.scope==='market')marketHints();}
 if(x.dataset.ri==='qty')recipeRows[+x.closest('[data-index]').dataset.index].qty=+x.value;
 if(x.name==='csvText'){importPreview=null;$('#import-result').innerHTML='';}});
document.addEventListener('change',e=>{const x=e.target;
 if(x.dataset.catColor!==undefined){const c=catList()[+x.dataset.catColor];if(c)commit((s,p)=>{p.categoryColors[c]=x.value.toLowerCase();},'Color changed');return;}
 if(x.id==='order-kind'){UI.orders.kind=x.value;UI.orders.page=0;render();}
 if(x.id==='recipe-cat'){UI.recipes.cat=x.value;render();}if(x.id==='recipe-sort'){UI.recipes.sort=x.value;render();}
 if(x.id==='recipe-pic-file'&&x.files[0]){readPicture(x.files[0]).then(d=>{recipeImg=d;$('#recipe-pic').innerHTML=imgBox(d,'');}).catch(err=>formError(err.message));x.value='';}
 if(x.dataset.sim==='payment'){simDraft.payment=x.value;updateSimulation();}
 if(x.dataset.line==='recipeId'){const lines=rowsOf(x.dataset.scope),i=+x.closest('[data-index]').dataset.index,r=recipe(x.value);lines[i]={...lines[i],recipeId:r.id,unitPrice:r.unitPrice,finishMinutes:r.finishMinutes};redrawRows(x.dataset.scope);}
 if(x.dataset.ri==='ingredientId'){recipeRows[+x.closest('[data-index]').dataset.index].ingredientId=x.value;$('#recipe-rows').innerHTML=ingRows();}
 if(x.dataset.navToggle){const k=x.dataset.navToggle;commit((s,p)=>{const h=p.hiddenNav.filter(v=>v!==k);if(!x.checked)h.push(k);p.hiddenNav=h;},x.checked?'Shown in the sidebar':'Hidden from the sidebar');}
 if(x.id==='week-picker'&&/^\d{4}-\d{2}-\d{2}$/.test(x.value))setWeek(x.value);
 if(x.id==='restore-file'&&x.files[0]){const f=x.files[0];x.value='';readBackup(f).then(b=>ask('Restore this backup?',`${plural(b.data.orders.length,'order')}, ${plural(b.data.recipes.length,'recipe')} and ${plural(b.data.ingredients.length,'ingredient')} from ${esc(b.data.settings.business)}. It replaces your ${demo?'own ':''}bakery in this browser; you can undo straight after.`,'Restore',()=>restoreFrom(b),false)).catch(err=>toast(err.message));}
 if(x.id==='csv-file'&&x.files[0]){const f=x.files[0];x.value='';if(f.size>4*1024*1024)return toast('The CSV must be under 4 MB.');f.text().then(t=>{const a=$('[name=csvText]');if(a){a.value=t;previewImport();}}).catch(()=>toast('That CSV couldn’t be read.'));}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,id=f.dataset.id;
 if(f.id==='ingredient-form')formSave(f,(s,d)=>{d.packCost=d.packCost===''?null:d.packCost;d.allergens=new FormData(f).getAll('allergens');return id?C.updateIngredient(s,id,d):C.addIngredient(s,d);},id?'Ingredient saved':'Ingredient added');
 if(f.id==='recipe-form')formSave(f,(s,d,p)=>{d.ingredients=recipeRows;const r=id?C.updateRecipe(s,id,d):C.addRecipe(s,d);if(recipeImg===null)delete p.images[r.id];else if(recipeImg)p.images[r.id]=recipeImg;return r;},id?'Recipe saved':'Recipe added');
 if(f.id==='order-form')formSave(f,(s,d)=>C.updateOrder(s,id,{...d,lines:orderRows}),'Order saved');
 if(f.id==='payment-form')formSave(f,(s,d)=>C.recordPayment(s,id,d.paid),'Payment recorded');
 if(f.id==='receive-form')formSave(f,(s,d)=>C.receiveIngredient(s,id,d.qty),'Stock added to the pantry');
 if(f.id==='settings-form'){if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));commit(s=>{s.settings={...s.settings,business:d.business,currency:d.currency,hourlyRate:+d.hourlyRate,targetMargin:+d.targetMargin,cardRate:+d.cardRate,fixedFee:+d.fixedFee};},'Settings saved');}
 if(f.id==='labels-form'){const d=Object.fromEntries(new FormData(f));commit(s=>{s.settings={...s.settings,address:d.address.trim(),labelFooter:d.labelFooter.trim()};},'Label details saved');}
 if(f.id==='capacity-form'){if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));commit(s=>{s.settings.capacity=Array.from({length:7},(_,n)=>Math.round(+d['cap'+n]*60));},'Working hours saved');}
 if(f.id==='cat-add-form'){const name=new FormData(f).get('name').trim();if(!name)return;if(catList().some(c=>c.toLowerCase()===name.toLowerCase()))return toast('That category already exists.');const color=new FormData(f).get('color');commit((s,p)=>{p.categories=[...catList(),name];if(/^#[0-9a-f]{6}$/i.test(color))p.categoryColors[name]=color;},'Category added');}
 if(f.id==='cat-form'){const old=f.dataset.old,name=new FormData(f).get('name').trim();if(name!==old&&catList().some(c=>c.toLowerCase()===name.toLowerCase()))return formError('That category already exists.');formSave(f,(s,d,p)=>{for(const r of s.recipes.filter(r=>r.category===old))C.updateRecipe(s,r.id,{category:name});p.categories=catList().map(c=>c===old?name:c);if(name!==old){p.categoryColors[name]=catColor(old);delete p.categoryColors[old];}},'Category renamed');}
 if(f.id==='sim-form')ACTIONS['accept-sim']();});

/* ---------- start ---------- */
$$('[data-action="prev-week"]').forEach(b=>b.innerHTML=ico('left'));$$('[data-action="next-week"]').forEach(b=>b.innerHTML=ico('right'));
$('.mobile-menu').innerHTML=ico('menu');$('.topbar [data-go="guide"]').innerHTML=ico('help')+'<span>Guide</span>';$('.topbar [data-action="backup"]').innerHTML=ico('down')+'<span>Back up</span>';
$('#rail-note').innerHTML=CONFIG.railNote;$('#rail-version').textContent=`${CONFIG.tagline} · v${CONFIG.version}`;
Promise.all([load(),initFolder()]).then(()=>{if(new URLSearchParams(location.search).get('demo')==='1')toggleSample(true);render();startupPrompt();});
